function compute_spectrum(truth):
    counts <- {T:0, F:0, B:0, N:0}
    for s in domain(truth):
        counts[truth[s]] += 1
    return counts

function audit(truth):
    sp <- compute_spectrum(truth)
    conservation <- (sp.T + sp.F + sp.B + sp.N == |truth|)
    degree <- sp.B
    has_T <- sp.T >= 1;  has_F <- sp.F >= 1
    tolerance_ok <- (not (has_T and has_F)) or (degree <= |truth| - 2)
    explosive <- (degree >= 1) and all(is_true(truth[s]) for s in truth)
    return (sp, degree, conservation, tolerance_ok, explosive)

